$utf8 = New-Object System.Text.UTF8Encoding $false
$sha = [Security.Cryptography.SHA256]::Create()
function Txt([string]$s) { [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($s)) }
function Las([string]$fil) { $p = Join-Path $Rot $fil; if (Test-Path -LiteralPath $p) { [IO.File]::ReadAllText($p).Replace("`r`n", "`n") } else { $null } }
function Hash($t) { if ($t -eq $null) { return 'saknas' }; $u = (($t -split "`n") | ForEach-Object { $_.TrimEnd() }) -join "`n"; -join ($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($u.Trim())) | ForEach-Object { $_.ToString('x2') }) }
function Antal([string]$t, [string]$s) { ([regex]::Matches($t, [regex]::Escape($s))).Count }
